// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // c's constructor sets bank = msg.sender (this test contract), so a winning
    // draw transfers the fee here; accept it so the reference never reverts.
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // plain EOA player

        vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: play() reverts iff the payment is not exactly the
        // ticket price. The reference always satisfies this; the mutant
        // reverts even for a correct ticket payment on a winning draw
        // (pot - FEE_AMOUNT underflows), which the fuzzer will hit.
        assertTrue(ok == (amount == c.TICKET_AMOUNT()));
    }
}

