pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET_AMOUNT = 10;
    uint constant FEE_AMOUNT = 1;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 ts, uint64 diff, address actor) public {
        // Admissible domain: player is a plain, distinct account
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        // Set the block context that feeds the lottery
        vm.warp(ts);
        vm.roll(diff);

        // Only admissible scenario: the play WINS the pot (random == 0)
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random == 0);

        // Player pays the exact ticket price
        vm.deal(actor, TICKET_AMOUNT);

        uint potBefore = c.pot();
        vm.prank(actor);
        (bool ok,) = address(c).call{value: TICKET_AMOUNT}(abi.encodeWithSignature("play()"));
        assertTrue(ok);

        // General rule: a winning play pays out the entire pot and resets it to 0.
        // The mutant leaves pot == 1, breaking this for every winning input.
        assertTrue(c.pot() == 0, "winning play must reset pot to 0");
    }
}

