pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 t) public {
        // Admissible domain: any timestamp; ticket value is fixed by the contract's require.
        vm.warp(t);

        // Fresh contract: before play, pot + balance == 0.
        // After one play of 10 wei, the reference always ends with pot + balance == 10
        // (no win, pot holds the ticket) or == 0 (win: bank got 1, player got 9, pot reset).
        // The mutant ends with pot == 1 and balance == 0 after a win: total == 1.
        address actor = address(0xA11CE);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        uint total = c.pot() + address(c).balance;
        assertTrue(total == 0 || total == 10);
    }

    // The contract is its own bank (deployed by this test); it must accept the 1 wei fee transfer.
    receive() external payable {}
}

