pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ts, uint256 blockNum, address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(c));
        vm.assume(uint160(player) > 10); // keep transfer targets safe (predeploys)
        vm.warp(ts);
        vm.roll(blockNum);
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();
        uint256 r = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        // Reference: payout/reset only on random==0, so after one play pot is 10 when r==1 and 0 when r==0.
        assertTrue(r == 1 ? c.pot() == 10 : c.pot() == 0);
    }
}

