contract InvMutTest {
    C c;
    bool __armed;
    bool __obsd;
    uint __snap;
    uint __potAfterFirst;

    constructor(C _c) { c = _c; }

    function run(uint amount1, uint amount2) public payable {
        require(amount1 == 10 && amount2 == 10);
        require(address(this).balance >= amount1 + amount2);
        c.play{value: amount1}();
        __potAfterFirst = c.pot();
        __armed = true;
        c.play{value: amount2}();
        __armed = false;
        assert(__potAfterFirst == 0 || __snap == __potAfterFirst + amount2);
    }

    receive() external payable {
        if (__armed && !__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

